    I18n.localize = function(root) {
        const words = chrome[this.locale];
        if (!words || !root) return;
        const blocked = '.part-name,.product-title-lg,.line-item-name,.b2b-suggestion-info,.model-tag,.model-option,[data-name]';
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        const nodes = [];
        while (walker.nextNode()) nodes.push(walker.currentNode);
        nodes.forEach(node => {
            if (node.parentElement?.closest(blocked)) return;
            const value = node.nodeValue.trim();
            if (words[value]) node.nodeValue = node.nodeValue.replace(value, words[value]);
        });
        root.querySelectorAll('[placeholder]').forEach(input => {
            const value = input.getAttribute('placeholder');
            if (words[value]) input.setAttribute('placeholder', words[value]);
        });
        root.querySelectorAll('[aria-label],[title]').forEach(el => ['aria-label','title'].forEach(attr => {
            const value = el.getAttribute(attr); if (words[value]) el.setAttribute(attr, words[value]);
        }));
    };
